using System.Windows;
using System.Windows.Automation.Peers;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Effects;

namespace ArcWpf.Controls;

/// <summary>Replaceable visual container generated by AvatarGroup; not a selectable item.</summary>
public class AvatarGroupItem : Control
{
    public static readonly DependencyProperty MemberProperty = DependencyProperty.Register(nameof(Member), typeof(AvatarGroupMember), typeof(AvatarGroupItem), new PropertyMetadata(null));
    public static readonly DependencyProperty SizeProperty = DependencyProperty.Register(nameof(Size), typeof(AvatarSize), typeof(AvatarGroupItem), new PropertyMetadata(AvatarSize.Medium));
    public static readonly DependencyProperty DiameterProperty = DependencyProperty.Register(nameof(Diameter), typeof(double), typeof(AvatarGroupItem), new PropertyMetadata(36d));
    public static readonly DependencyProperty RingBrushProperty = DependencyProperty.Register(nameof(RingBrush), typeof(Brush), typeof(AvatarGroupItem), new PropertyMetadata(null, (d, _) => ((AvatarGroupItem)d).UpdateRing(true)));
    public AvatarGroupMember? Member { get => (AvatarGroupMember?)GetValue(MemberProperty); private set => SetValue(MemberProperty, value); }
    public AvatarSize Size { get => (AvatarSize)GetValue(SizeProperty); private set => SetValue(SizeProperty, value); }
    public double Diameter { get => (double)GetValue(DiameterProperty); private set => SetValue(DiameterProperty, value); }
    public Brush? RingBrush { get => (Brush?)GetValue(RingBrushProperty); set => SetValue(RingBrushProperty, value); }
    internal string GroupLabel { get; set; } = "Team members";
    internal bool IsExiting { get; set; }
    internal bool IsClosing { get; private set; }
    internal int Count { get; private set; }
    private readonly AvatarGroup? _owner;
    private readonly OwnedMotion _presence = new(), _hover = new(), _count = new(), _color = new();
    private FrameworkElement? _lift;
    private Border? _tip, _ring, _overflow;
    private TextBlock? _currentCount, _oldCount;
    private TranslateTransform? _liftTransform, _tipTransform;
    private readonly ScaleTransform _scale = new(1, 1);
    private SolidColorBrush? _ringBrush;
    private bool _tipShown, _observing;
    internal bool IsMotionRunning => _presence.IsRunning || _hover.IsRunning || _count.IsRunning || _color.IsRunning;
    private bool CanAnimate => IsLoaded && IsVisible && ArcMotion.GetLevel(this) != ArcMotionLevel.Off;
    private bool Full => ArcMotion.GetLevel(this) == ArcMotionLevel.Full;
    static AvatarGroupItem()
    {
        DefaultStyleKeyProperty.OverrideMetadata(typeof(AvatarGroupItem), new FrameworkPropertyMetadata(typeof(AvatarGroupItem)));
        FocusableProperty.OverrideMetadata(typeof(AvatarGroupItem), new FrameworkPropertyMetadata(false));
        IsTabStopProperty.OverrideMetadata(typeof(AvatarGroupItem), new FrameworkPropertyMetadata(false));
    }
    public AvatarGroupItem() { RenderTransform = _scale; RenderTransformOrigin = new Point(.5, .5); Loaded += (_, _) => ObserveMember(); Unloaded += (_, _) => { Stop(); UnobserveMember(); }; }
    internal AvatarGroupItem(AvatarGroup owner, AvatarGroupMember? member) : this() { _owner = owner; Member = member; SetResourceReference(RingBrushProperty, "ArcWpf.Brush.Border"); }
    private void ObserveMember() { if (_observing || Member is null) return; Member.PropertyChanged += MemberChanged; _observing = true; }
    private void UnobserveMember() { if (_observing && Member is not null) Member.PropertyChanged -= MemberChanged; _observing = false; }
    private void MemberChanged(object? sender, System.ComponentModel.PropertyChangedEventArgs e) => UIElementAutomationPeer.FromElement(this)?.InvalidatePeer();
    public override void OnApplyTemplate()
    {
        DetachTemplate(); base.OnApplyTemplate();
        _lift = GetTemplateChild("PART_Lift") as FrameworkElement;
        _tip = GetTemplateChild("PART_Tip") as Border;
        _ring = GetTemplateChild("PART_Ring") as Border;
        _overflow = GetTemplateChild("PART_Overflow") as Border;
        _currentCount = GetTemplateChild("PART_Count") as TextBlock;
        _oldCount = GetTemplateChild("PART_OldCount") as TextBlock;
        if (_lift is not null) { _liftTransform = new TranslateTransform(); _lift.RenderTransform = _liftTransform; }
        if (_tip is not null) { _tipTransform = new TranslateTransform(); _tip.RenderTransform = _tipTransform; _tip.SizeChanged += TipSizeChanged; _tip.Opacity = 0; }
        if (_currentCount is not null) _currentCount.Text = $"+{Count}";
        if (_oldCount is not null) _oldCount.Opacity = 0;
        UpdateShape(); UpdateRing(false);
    }
    protected override void OnTemplateChanged(ControlTemplate oldTemplate, ControlTemplate newTemplate) { DetachTemplate(); base.OnTemplateChanged(oldTemplate, newTemplate); }
    private void DetachTemplate()
    {
        _hover.Stop(); _count.Stop(); _color.Stop();
        if (_tip is not null) _tip.SizeChanged -= TipSizeChanged;
        _tip = _ring = _overflow = null; _lift = null; _currentCount = _oldCount = null; _liftTransform = _tipTransform = null; _ringBrush = null; _tipShown = false;
    }
    internal void SetGeometry(double diameter, AvatarSize size)
    {
        bool changed = Diameter != diameter; Diameter = diameter; Size = size; Height = diameter;
        if (changed) { _presence.Stop(); Width = diameter - 6; Opacity = 1; _scale.ScaleX = _scale.ScaleY = 1; }
        UpdateShape();
    }
    private void UpdateShape()
    {
        if (_ring is not null) { _ring.Width = _ring.Height = Diameter + 2; _ring.CornerRadius = new CornerRadius((Diameter + 2) / 2); }
        if (_overflow is not null) { _overflow.CornerRadius = new CornerRadius(Diameter / 2); _overflow.Clip = new EllipseGeometry(new Point(Diameter / 2, Diameter / 2), Diameter / 2, Diameter / 2); }
        PositionTip();
    }
    internal void SetPresence(bool present, bool animate, bool created, Action? completed = null)
    {
        if (present && !created && !IsClosing) return;
        IsClosing = !present;
        if (created) { Width = animate ? 0 : Diameter - 6; Opacity = animate ? 0 : 1; _scale.ScaleX = _scale.ScaleY = animate ? .9 : 1; }
        _presence.Double(this, WidthProperty, present ? Diameter - 6 : 0, .42, animate, spring: true, completed: completed);
        _presence.Double(this, OpacityProperty, present ? 1 : 0, .42, animate, spring: true);
        _presence.Double(_scale, ScaleTransform.ScaleXProperty, present ? 1 : .9, .42, animate, spring: true);
        _presence.Double(_scale, ScaleTransform.ScaleYProperty, present ? 1 : .9, .42, animate, spring: true);
    }
    internal void SetCount(int value, bool animate)
    {
        if (Count == value) return;
        int old = Count; Count = value; UIElementAutomationPeer.FromElement(this)?.InvalidatePeer();
        if (_currentCount is null || _oldCount is null) return;
        _count.Stop(); bool moving = animate && CanAnimate && old > 0;
        _oldCount.Text = $"+{old}"; _currentCount.Text = $"+{value}";
        _oldCount.Opacity = moving ? 1 : 0; _currentCount.Opacity = moving ? 0 : 1;
        int direction = value >= old ? 1 : -1; double distance = FontSize * .4 * direction;
        var incoming = new TranslateTransform(0, moving && Full ? distance : 0); var outgoing = new TranslateTransform();
        _currentCount.RenderTransform = incoming; _oldCount.RenderTransform = outgoing;
        _currentCount.Effect = _oldCount.Effect = null;
        if (!moving) return;
        _count.Double(_currentCount, OpacityProperty, 1, Full ? .24 : .12, true, enter: true);
        _count.Double(_oldCount, OpacityProperty, 0, Full ? .16 : .12, true);
        if (Full)
        {
            var inBlur = new BlurEffect { Radius = 2 }; var outBlur = new BlurEffect(); _currentCount.Effect = inBlur; _oldCount.Effect = outBlur;
            _count.Double(incoming, TranslateTransform.YProperty, 0, .24, true, enter: true);
            _count.Double(outgoing, TranslateTransform.YProperty, -distance, .16, true);
            _count.Double(inBlur, BlurEffect.RadiusProperty, 0, .24, true, enter: true);
            _count.Double(outBlur, BlurEffect.RadiusProperty, 2, .16, true);
        }
    }
    internal void SetHover(double x, double y, bool selected, bool animate)
    {
        bool moving = animate && CanAnimate && Full;
        if (!Full) x = y = 0;
        if (_liftTransform is not null)
        {
            _hover.Double(_liftTransform, TranslateTransform.XProperty, x, .24, moving);
            _hover.Double(_liftTransform, TranslateTransform.YProperty, y, .24, moving);
        }
        SetResourceReference(RingBrushProperty, selected ? "ArcWpf.Brush.BorderStrong" : "ArcWpf.Brush.Border");
        if (_tip is not null && _tipTransform is not null)
        {
            bool show = selected && Member is not null;
            double delay = show && !_tipShown && moving ? .06 : 0;
            _hover.Double(_tip, OpacityProperty, show ? 1 : 0, .16, moving, delay: delay);
            _hover.Double(_tipTransform, TranslateTransform.YProperty, Full && !show ? 3 : 0, .16, moving, delay: delay);
            _tipShown = show;
        }
    }
    private void TipSizeChanged(object sender, SizeChangedEventArgs e) => PositionTip();
    private void PositionTip()
    {
        if (_tip is null) return;
        Canvas.SetLeft(_tip, (Diameter - _tip.ActualWidth) / 2); Canvas.SetTop(_tip, -_tip.ActualHeight - 8); _tip.CornerRadius = new CornerRadius(_tip.ActualHeight / 2);
    }
    private void UpdateRing(bool animate)
    {
        if (_ring is null) return;
        if (RingBrush is SolidColorBrush target)
        { _ringBrush ??= new SolidColorBrush(target.Color); _ring.BorderBrush = _ringBrush; _color.Color(_ringBrush, target.Color, .16, animate && CanAnimate); }
        else _ring.BorderBrush = RingBrush;
    }
    protected override void OnMouseEnter(MouseEventArgs e) { base.OnMouseEnter(e); if (e.StylusDevice is null && !IsExiting) _owner?.Pointer(this, true); }
    protected override void OnMouseLeave(MouseEventArgs e) { base.OnMouseLeave(e); _owner?.Pointer(this, false); }
    internal void Settle()
    {
        Stop(); IsClosing = false; Width = Diameter - 6; Opacity = 1; _scale.ScaleX = _scale.ScaleY = 1;
        if (_oldCount is not null) { _oldCount.Opacity = 0; _oldCount.Effect = null; }
        if (_currentCount is not null) { _currentCount.Opacity = 1; _currentCount.RenderTransform = Transform.Identity; _currentCount.Effect = null; }
    }
    private void Stop() { _presence.Stop(); _hover.Stop(); _count.Stop(); _color.Stop(); }
    internal void DisposeVisual() { UnobserveMember(); Stop(); DetachTemplate(); System.Windows.Data.BindingOperations.ClearAllBindings(this); }
    protected override AutomationPeer OnCreateAutomationPeer() => new ItemPeer(this);
    private sealed class ItemPeer(AvatarGroupItem owner) : FrameworkElementAutomationPeer(owner)
    {
        protected override string GetClassNameCore() => nameof(AvatarGroupItem);
        protected override AutomationControlType GetAutomationControlTypeCore() => AutomationControlType.Image;
        protected override string GetNameCore() => owner.Member is { } m ? (m.DisplayName ?? "") + (m.Status == AvatarStatus.None ? "" : $", {m.Status.ToString().ToLowerInvariant()}") : $"{owner.Count} more {owner.GroupLabel.ToLowerInvariant()}";
        protected override List<AutomationPeer>? GetChildrenCore() => null;
        protected override bool IsControlElementCore() => !owner.IsExiting;
        protected override bool IsContentElementCore() => !owner.IsExiting;
    }
}
